<template>
  <section class="pc-page" :aria-busy="loading">
    <VnetBackButton to="/?entry=tools" />
    <header class="pc-head"><div class="pc-title"><ClipboardCheck :size="23" /><h2>计划收敛审查</h2></div><div class="pc-actions"><span v-if="loadedAt" class="muted">屏蔽列表 {{ timeText(loadedAt) }}</span><button v-if="tab === 'review'" :disabled="loading || listLoading" @click="loadBlocks"><RefreshCw :size="16" :class="{ spin: listLoading }" />刷新屏蔽记录</button><button v-if="boot.is_admin" class="pc-icon" title="平台设置" aria-label="平台设置" :disabled="loading" @click="openSettings"><Settings :size="18" /></button></div></header>
    <nav class="pc-tabs" aria-label="计划收敛功能"><button v-for="item in tabs" :key="item.id" :class="{ active: tab === item.id }" :aria-current="tab === item.id ? 'page' : undefined" @click="switchTab(item.id)"><component :is="item.icon" :size="17" />{{ item.label }}</button></nav>
    <div class="pc-alert warning" role="status"><AlertCircle :size="18" /><span>智航查询需要运行灯塔的电脑连接 VPN。未连接时仅智航查询不可用，其他功能和本地规则配置不受影响。</span></div>
    <div v-if="error" class="pc-alert error" role="alert"><AlertCircle :size="18" /><span>{{ error }}</span><button class="pc-icon" aria-label="关闭提示" @click="error = ''"><X :size="16" /></button></div>
    <div v-if="notice" class="pc-alert success" role="status"><CheckCircle2 :size="18" />{{ notice }}</div>
    <div v-if="!loading && !boot.catalog_ready" class="pc-alert warning"><AlertCircle :size="18" />本机尚未放置目录数据，请将 catalog.sqlite3 放入 bin/data/plan_convergence 后刷新。</div>
    <div v-if="loading" class="pc-empty"><Loader2 :size="24" class="spin" />正在加载…</div>

    <div v-show="tab === 'review'" class="pc-review">
      <aside class="pc-list">
        <div class="pc-section-head"><h3>屏蔽记录 <small>{{ filteredBlocks.length }}</small></h3><span class="pc-badge">屏蔽中 {{ activeCount }}</span></div>
        <div class="pc-list-filters"><input v-model="search" type="search" aria-label="搜索屏蔽记录" placeholder="搜索名称或 ID" /><VnetSelect input-id="pc-block-status" v-model="status" :options="['全部状态', '屏蔽中', '已关闭']" label="屏蔽状态" /></div>
        <div v-if="listLoading" class="pc-empty"><Loader2 :size="20" class="spin" />正在读取屏蔽列表…</div>
        <div v-else-if="!filteredBlocks.length" class="pc-empty">{{ blocks.length ? '没有匹配记录' : '暂无屏蔽记录' }}<button v-if="!blocks.length" :disabled="listLoading" @click="loadBlocks"><RefreshCw :size="16" />拉取记录</button></div>
        <div v-else class="pc-records"><button v-for="row in blockPageRows" :key="blockId(row)" class="pc-record" :class="{ selected: selectedId === blockId(row) }" @click="chooseBlock(blockId(row))"><strong>{{ row.blockName || '未命名屏蔽' }}</strong><span><small>{{ blockId(row) }}</small><b class="pc-badge" :class="String(row.status) === '1' ? 'green' : 'neutral'">{{ String(row.status) === '1' ? '屏蔽中' : '已关闭' }}</b></span><small>{{ row.startTime || row.creatTime || '—' }}</small></button></div>
        <div class="pc-pager"><button class="pc-icon" aria-label="上一页屏蔽记录" :disabled="blockPage <= 1" @click="blockPage--"><ChevronLeft :size="17" /></button><span>{{ blockPage }} / {{ blockPages }}</span><button class="pc-icon" aria-label="下一页屏蔽记录" :disabled="blockPage >= blockPages" @click="blockPage++"><ChevronRight :size="17" /></button></div>
      </aside>
      <main class="pc-main">
        <form class="pc-query pc-actions" @submit.prevent="chooseBlock(queryId)"><label>屏蔽 ID<input v-model="queryId" inputmode="numeric" placeholder="输入屏蔽 ID" /></label><button class="primary" :disabled="detailLoading || !queryId.trim()"><Search :size="16" />查询详情</button></form>
        <div v-if="detailLoading" class="pc-empty"><Loader2 :size="22" class="spin" />正在读取记录详情…</div>
        <div v-else-if="!detail" class="pc-empty"><ClipboardCheck :size="30" />选择一条屏蔽记录</div>
        <template v-else>
          <div class="pc-section-head"><h3>{{ detail.blockName || '屏蔽记录' }}</h3><button class="pc-icon" title="记录详情" aria-label="查看记录全部信息" @click="showFields(detail, '屏蔽记录信息')"><Info :size="17" /></button></div>
          <dl class="pc-metadata"><div><dt>创建人</dt><dd>{{ detail.userName || '—' }}</dd></div><div><dt>开始时间</dt><dd>{{ detail.startTime || '—' }}</dd></div><div><dt>结束时间</dt><dd>{{ detail.endTime || '—' }}</dd></div><div><dt>屏蔽明细</dt><dd>{{ detailRows.length }} 项</dd></div></dl>
          <div class="pc-table-wrap"><table><thead><tr><th>设备类型</th><th>关联资源</th><th>告警规则</th><th>关联设备</th><th class="pc-actions-cell">查看</th></tr></thead><tbody><tr v-for="(row, n) in detailPageRows" :key="row.blockDetailId || n"><td>{{ row.classifyModel || row.classifyModelName || row.domainCode || '—' }}</td><td>{{ row.spaceModel || row.spaceModelName || '—' }}</td><td>{{ row.relateConfig || row.alarmConfigId || '—' }}</td><td>{{ row.instances || row.instanceIds || '—' }}</td><td><div class="pc-row-tools"><button class="pc-icon" title="明细信息" aria-label="查看明细信息" @click="showFields(row, '屏蔽明细')"><Info :size="15" /></button><button class="pc-icon" title="实例快照" aria-label="查看实例快照" @click="drill(row, 'snapshots')"><Camera :size="15" /></button><button class="pc-icon" title="规则视图" aria-label="查看规则视图" @click="drill(row, 'rule-view')"><ListFilter :size="15" /></button><button class="pc-icon" title="本地测点" aria-label="查看本地测点" :disabled="!boot.points_ready" @click="showPoints(row)"><Activity :size="15" /></button></div></td></tr><tr v-if="!detailRows.length"><td colspan="5" class="muted">此记录没有屏蔽明细</td></tr></tbody></table></div>
          <div v-if="detailPages > 1" class="pc-pager"><button class="pc-icon" aria-label="上一页明细" :disabled="detailPage <= 1" @click="detailPage--"><ChevronLeft :size="17" /></button><span>{{ detailPage }} / {{ detailPages }}</span><button class="pc-icon" aria-label="下一页明细" :disabled="detailPage >= detailPages" @click="detailPage++"><ChevronRight :size="17" /></button></div>
          <section class="pc-match">
            <div class="pc-section-head"><h3>规则集核对</h3><button class="pc-icon" title="刷新规则集" aria-label="刷新规则集" @click="loadRuleSets"><RefreshCw :size="15" /></button></div>
            <div class="pc-actions"><VnetSelect input-id="pc-rule-set" :model-value="setLabel" :options="setOptions" label="规则集" placeholder="请选择规则集" :disabled="matchLoading" @update:model-value="setId = String(ruleSets.find(s => ruleSetLabel(s) === $event)?.id || '')" /><button class="primary" :disabled="matchLoading || !setId" @click="matchRules"><Loader2 v-if="matchLoading" :size="16" class="spin" /><ClipboardCheck v-else :size="16" />{{ matchLoading ? '核对中…' : '核对规则集' }}</button></div>
            <template v-if="matchResult"><p class="muted">{{ matchResult.source_name }} · {{ matchResult.checked_at }}</p><div class="pc-alert" :class="matchResult.passed ? 'success' : 'warning'"><CheckCircle2 v-if="matchResult.passed" :size="18" /><AlertCircle v-else :size="18" /><strong>{{ matchResult.passed ? '核对通过' : '存在未覆盖或未识别的设备' }}</strong><span>规则集 {{ matchResult.set_device_count }} 台 · 屏蔽记录 {{ matchResult.record_device_count }} 台</span></div><div class="pc-groups"><button v-for="group in matchGroups" :key="group.kind + group.group_no" class="pc-group" @click="showGroup(group)"><span class="pc-badge" :class="group.kind === '公共' ? 'amber' : ''">{{ group.kind }}</span><strong>{{ group.label }}</strong><span :class="group.matched ? 'good' : 'bad'">{{ group.matched ? '已覆盖' : group.device_count === 0 ? '规则未包含设备' : '缺少 ' + group.missing_count + ' 台' }}</span><Eye :size="15" /></button></div><p v-if="matchResult.not_found_devices?.length" class="pc-alert warning">目录中未找到：{{ matchResult.not_found_devices.join('、') }}</p></template>
          </section>
          <details class="pc-excel"><summary>Excel 场景核验<span v-if="excelFilename" class="muted"> · {{ excelFilename }}</span></summary><div class="pc-actions"><label class="pc-upload"><FileUp :size="16" />上传场景 Excel<input type="file" accept=".xlsx,.xlsm" :disabled="excelLoading" @change="uploadExcel" /></label><VnetSelect v-if="sheets.length" input-id="pc-excel-sheet" v-model="sheetName" :options="sheets.map(s => s.name)" label="场景工作表" :disabled="excelLoading" /><button class="primary" :disabled="excelLoading || !sheetName" @click="compareExcel"><Loader2 v-if="excelLoading" :size="16" class="spin" /><ClipboardCheck v-else :size="16" />{{ excelLoading ? '核验中…' : '核验场景' }}</button><button v-if="excelResult?.missing_data_list?.length" @click="downloadGaps"><Download :size="16" />导出补配清单</button></div><template v-if="excelResult"><p class="muted">{{ excelResult.source_name }} · {{ excelResult.checked_at }}</p><div class="pc-alert" :class="excelResult.passed ? 'success' : 'warning'">{{ excelResult.passed ? '场景核验通过' : '场景存在缺项' }} · 原表 {{ excelResult.stats?.expected_row_count }} 行 · 缺项 {{ excelResult.missing_data_list?.length || 0 }} 组</div><div v-if="excelResult.missing_data_list?.length" class="pc-table-wrap"><table><thead><tr><th>原行号</th><th>设备域 / 资源</th><th>需要补配</th></tr></thead><tbody><tr v-for="(gap,n) in excelResult.missing_data_list" :key="n"><td>{{ gap.row_numbers?.join('、') }}</td><td>{{ gap['设备域'] }} / {{ gap['关联资源'] }}</td><td>{{ gap.message }}</td></tr></tbody></table></div></template></details>
        </template>
      </main>
    </div>
    <PlanConvergenceRules v-if="visitedRules" v-show="tab === 'rules'" ref="rulesRef" :is-admin="Boolean(boot.is_admin)" />
    <section v-if="visitedMaintenance" v-show="tab === 'maintenance'" class="pc-maintenance">
      <div class="pc-toolbar"><div class="pc-actions"><input v-model="maintenanceSearch" type="search" placeholder="搜索检修名称、设备或位置" aria-label="搜索检修记录" /></div><div class="pc-actions"><button :disabled="maintenanceLoading || checking" @click="loadMaintenance"><RefreshCw :size="16" />刷新检修记录</button><button class="primary" :disabled="checking || maintenanceLoading" @click="checkMaintenance()"><Loader2 v-if="checking" :size="16" class="spin" /><ClipboardCheck v-else :size="16" />{{ checking ? '正在核对…' : '核对进行中检修' }}</button></div></div>
      <div v-if="maintenanceStats" class="pc-statline"><span>检修 {{ maintenanceStats.maintenance }}</span><span>屏蔽 {{ maintenanceStats.blocks }}</span><span class="good">已匹配 {{ maintenanceStats.matched_records }}</span><span class="bad">未匹配屏蔽 {{ maintenanceStats.orphan_blocks }}</span></div>
      <div v-if="maintenanceLoading" class="pc-empty"><Loader2 :size="22" class="spin" />正在读取检修记录…</div><div v-else-if="!maintenanceFiltered.length" class="pc-empty">暂无匹配的检修记录</div>
      <div v-else class="pc-table-wrap"><table><thead><tr><th>检修记录</th><th>楼栋 / 状态</th><th>设备 / 位置</th><th>核对结果</th><th>操作</th></tr></thead><tbody><tr v-for="row in maintenancePageRows" :key="row.record_id"><td><strong>{{ row.name }}</strong><small>{{ row.fault || '—' }}</small></td><td>{{ row.building }}<span class="pc-badge">{{ row.status }}</span></td><td>{{ row.device || '—' }}<small>{{ row.location }} · {{ row.start_time || row.fault_time || '—' }}</small></td><td><span v-if="!('hits' in row)" class="muted">尚未核对</span><span v-else-if="!row.hits?.length" class="bad">未找到匹配屏蔽</span><button v-for="hit in row.hits || []" :key="hit.blockId" class="pc-hit" @click="chooseFromMaintenance(hit.blockId)"><CheckCircle2 :size="15" /><span>{{ hit.blockName || hit.blockId }}<small>{{ hit.reason }}</small></span><ChevronRight :size="15" /></button></td><td><button :disabled="checking" @click="checkMaintenance(row.record_id)"><ClipboardCheck :size="15" />核对</button></td></tr></tbody></table></div>
      <div class="pc-pager"><span>共 {{ maintenanceFiltered.length }} 条</span><button class="pc-icon" aria-label="上一页检修" :disabled="maintenancePage <= 1" @click="maintenancePage--"><ChevronLeft :size="17" /></button><span>{{ maintenancePage }} / {{ maintenancePages }}</span><button class="pc-icon" aria-label="下一页检修" :disabled="maintenancePage >= maintenancePages" @click="maintenancePage++"><ChevronRight :size="17" /></button></div>
    </section>

    <Teleport to="body"><UiTransition name="ui-overlay" appear>
    <div v-if="dialog.open" class="pc-overlay" @click.self="closeDialog"><section ref="dialogElement" class="pc-dialog" role="dialog" aria-modal="true" aria-labelledby="pc-dialog-title" tabindex="-1"><header><h3 id="pc-dialog-title">{{ dialog.title }}</h3><button class="pc-icon" aria-label="关闭弹窗" @click="closeDialog"><X :size="19" /></button></header><div class="pc-dialog-body"><div v-if="dialog.error" class="pc-alert error" role="alert">{{ dialog.error }}</div><div v-if="dialog.loading" class="pc-empty"><Loader2 :size="22" class="spin" />正在读取…</div>
      <form v-else-if="dialog.kind === 'settings'" id="pc-settings-form" class="pc-settings" @submit.prevent="saveSettings"><div class="pc-setting-status"><span class="muted">检修通告 · 当前程序全部楼栋未结束记录</span><span>目录 {{ boot.counts?.devices || 0 }} 台设备 · {{ boot.counts?.rules || 0 }} 条规则</span><span :class="boot.points_ready ? 'good' : 'bad'">本地测点 {{ boot.points_ready ? '可用' : '未放置 points.sqlite3' }}</span><span :class="settings.has_token && !settings.expired ? 'good' : 'bad'">智航 {{ settings.has_token ? (settings.expired ? '登录已过期' : (authAccount || '已连接')) : '未连接' }}</span></div><div class="pc-actions"><button type="button" :disabled="settingsBusy || loginBusy || loginActive" @click="startBrowserLogin"><Loader2 v-if="loginBusy || loginActive" :size="16" class="spin" /><LogIn v-else :size="16" />{{ loginBusy ? '正在启动…' : (loginActive ? loginStatusLabel : '登录智航') }}</button><button v-if="loginJob.job_id && loginActive" type="button" :disabled="settingsBusy || loginBusy" @click="cancelBrowserLogin"><X :size="16" />取消登录</button><button type="button" :disabled="settingsBusy || loginBusy || loginActive" @click="testSettings"><Activity :size="16" />测试连接</button></div><p v-if="loginJob.message" class="pc-alert" :class="loginAlertClass"><Loader2 v-if="loginActive" :size="16" class="spin" /><span>{{ loginStatusLabel }}{{ loginJob.message ? '：' + loginJob.message : '' }}</span></p><details class="pc-advanced"><summary>高级设置</summary><label>Token<textarea v-model="settings.token" rows="3" autocomplete="off" :placeholder="settings.has_token ? '已保存，留空保持不变' : '粘贴智航 Token（可选，留空则使用浏览器登录）'" :disabled="settingsBusy || loginActive || loginBusy" maxlength="12000" /></label><p v-if="settings.has_token" class="muted">当前 Token 属于 {{ settings.token_owner || '未知' }}，过期 {{ expiresText(settings.expires_at) }}</p></details></form>
      <template v-else><div class="pc-table-wrap"><table><thead><tr><th v-for="column in dialog.columns" :key="column.key">{{ column.label }}</th><th v-if="dialog.kind !== 'table'">操作</th></tr></thead><tbody><tr v-for="(row,n) in dialogPageRows" :key="row.inst_id || row.point_id || n"><td v-for="column in dialog.columns" :key="column.key">{{ valueText(row[column.key]) }}</td><td v-if="dialog.kind === 'instances'"><button @click="showInstancePoints(row)"><Activity :size="15" />查看测点</button></td><td v-else-if="dialog.kind === 'snapshots' || dialog.kind === 'rule-view'"><div class="pc-actions"><button class="pc-icon" title="查看全部信息" aria-label="查看全部信息" @click="showDialogRow(row)"><Info :size="16" /></button><button v-if="dialog.kind === 'snapshots'" class="pc-icon" title="本地测点" aria-label="查看本地测点" :disabled="!boot.points_ready" @click="showPoints({instances: row.insName})"><Activity :size="16" /></button></div></td></tr><tr v-if="!dialog.rows.length"><td :colspan="dialog.columns.length + 1" class="muted">暂无数据</td></tr></tbody></table></div></template>
      </div><footer><div v-if="dialog.kind !== 'settings'" class="pc-actions"><button v-if="dialog.previous" class="pc-icon" title="返回设备列表" aria-label="返回设备列表" @click="restoreDialog"><ArrowLeft :size="17" /></button><span class="muted">共 {{ dialog.rows.length }} 条</span><button class="pc-icon" aria-label="上一页弹窗记录" :disabled="dialogPage <= 1" @click="dialogPage--"><ChevronLeft :size="17" /></button><span>{{ dialogPage }} / {{ dialogPages }}</span><button class="pc-icon" aria-label="下一页弹窗记录" :disabled="dialogPage >= dialogPages" @click="dialogPage++"><ChevronRight :size="17" /></button></div><span v-else class="muted">{{ settingsBusy ? '正在处理…' : '' }}</span><div class="pc-actions"><button :disabled="settingsBusy" @click="closeDialog">关闭</button><button v-if="dialog.kind === 'settings'" class="primary" type="submit" form="pc-settings-form" :disabled="settingsBusy || dialog.loading || loginActive || loginBusy"><Save :size="16" />保存设置</button></div></footer></section></div>
    </UiTransition></Teleport>
    <ConfirmDialog :open="confirmOpen" title="有未保存的修改" message="离开后当前未保存的规则修改会丢失，是否继续？" confirm-label="离开" @resolve="resolveConfirm" />
  </section>
</template>

<script setup lang="ts">
import { computed, nextTick, onBeforeUnmount, onMounted, reactive, ref, watch } from 'vue';
import { Activity, AlertCircle, ArrowLeft, Camera, CheckCircle2, ChevronLeft, ChevronRight, ClipboardCheck, Download, Eye, FileUp, Info, Layers, ListFilter, Loader2, LogIn, RefreshCw, Save, Settings, Wrench, X } from 'lucide-vue-next';
import { requestJson, type Dict } from '../api/client';
import { acquireModal } from '../modalState';
import { navigate, registerNavigationGuard } from '../navigation';
import VnetBackButton from './VnetBackButton.vue';
import VnetSelect from './VnetSelect.vue';
import ConfirmDialog from './ConfirmDialog.vue';
import PlanConvergenceRules from './PlanConvergenceRules.vue';

type Tab = 'review' | 'rules' | 'maintenance';
type Column = { key: string; label: string };
const tabs: {id: Tab; label: string; icon: any}[] = [{id:'review',label:'核对台',icon:ClipboardCheck},{id:'rules',label:'规则配置',icon:Layers},{id:'maintenance',label:'检修核对',icon:Wrench}];
const tab = ref<Tab>('review'), visitedRules = ref(false), visitedMaintenance = ref(false);
const boot = ref<Dict>({}), loading = ref(true), error = ref(''), notice = ref('');
const rulesRef = ref<InstanceType<typeof PlanConvergenceRules> | null>(null);
const base = '/api/plan-convergence';
let disposed = false, detailRequest = 0;
const pageController = new AbortController();
const requestOptions = {signal: pageController.signal, timeoutMs: 90_000};
const post = (path:string,data:Dict,timeoutMs=90_000) => requestJson(base+path,{...requestOptions,method:'POST',body:JSON.stringify(data),timeoutMs});
function report(e:unknown) { if (!disposed) error.value = e instanceof Error ? e.message : String(e); }
function timeText(value:any) { if (!value) return '—'; const n=Number(value); if (!Number.isFinite(n)) return String(value); return new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}).format(new Date(n < 1e12 ? n*1000 : n)); }
function valueText(value:any):string { if (value == null || value === '') return '—'; if (Array.isArray(value)) return value.map(valueText).join('、'); if (typeof value === 'object') return Object.entries(value).map(([key,v])=>`${key}: ${valueText(v)}`).join('；'); return String(value); }
const blocks=ref<Dict[]>([]), loadedAt=ref(0), listLoading=ref(false), search=ref(''), status=ref('全部状态'), blockPage=ref(1);
const blockId=(row:Dict)=>String(row.blockId || row.id || '');
const activeCount=computed(()=>blocks.value.filter(row=>String(row.status)==='1').length);
const filteredBlocks=computed(()=>blocks.value.filter(row=>(status.value==='全部状态' || (String(row.status)==='1' ? '屏蔽中':'已关闭')===status.value) && `${row.blockName || ''} ${blockId(row)}`.toLowerCase().includes(search.value.trim().toLowerCase())));
const blockPages=computed(()=>Math.max(1,Math.ceil(filteredBlocks.value.length/20)));
const blockPageRows=computed(()=>filteredBlocks.value.slice((blockPage.value-1)*20,blockPage.value*20));
watch([search,status],()=>blockPage.value=1);
async function loadBlocks() { if(listLoading.value) return; listLoading.value=true; error.value=''; try { const data=await requestJson(base+'/blocks?refresh=1',{...requestOptions,timeoutMs:180_000}); if(!disposed){blocks.value=data.items;loadedAt.value=data.loaded_at;blockPage.value=1;} }catch(e){report(e);}finally{listLoading.value=false;} }
const selectedId=ref(''), queryId=ref(''), detail=ref<Dict|null>(null), detailLoading=ref(false), detailPage=ref(1);
const detailRows=computed<Dict[]>(()=>detail.value?.alarmBlockDetailResultList || []), detailPages=computed(()=>Math.max(1,Math.ceil(detailRows.value.length/25))), detailPageRows=computed(()=>detailRows.value.slice((detailPage.value-1)*25,detailPage.value*25));
async function chooseBlock(id:string) { if(!id.trim())return; const seq=++detailRequest; selectedId.value=id.trim(); queryId.value=id.trim();detail.value=null;matchResult.value=null;excelResult.value=null;detailLoading.value=true;error.value=''; try{const data=await requestJson(base+'/blocks/'+encodeURIComponent(id.trim()),requestOptions);if(seq===detailRequest && !disposed){detail.value=data;detailPage.value=1;}}catch(e){if(seq===detailRequest)report(e);}finally{if(seq===detailRequest)detailLoading.value=false;} }
const ruleSets=ref<Dict[]>([]), setId=ref(''), matchLoading=ref(false), matchResult=ref<Dict|null>(null);
const ruleSetLabel=(row:Dict)=>`${row.name}（${row.item_count || 0} 项）`;
const setOptions=computed(()=>ruleSets.value.map(ruleSetLabel)),setLabel=computed(()=>{const row=ruleSets.value.find(row=>String(row.id)===setId.value);return row?ruleSetLabel(row):'';});
const matchGroups=computed<Dict[]>(()=>[...(matchResult.value?.common?.groups||[]).map((g:Dict)=>({...g,kind:'公共'})),...(matchResult.value?.rules?.groups||[]).map((g:Dict)=>({...g,kind:'普通'}))]);
async function loadRuleSets(){matchRequest++;matchResult.value=null;try{const rows=await requestJson(base+'/rulesets',requestOptions);if(!disposed)ruleSets.value=rows as unknown as Dict[];}catch(e){report(e);}}
let matchRequest=0,excelRequest=0;
watch(setId,()=>{matchRequest++;matchResult.value=null;});
